class Solution {
public:
    int minLargest(vector<int>& nums1, vector<int>& nums2) {
        int m = nums1.size();
        int n = nums2.size();
        vector<vector<int>> dp(m + 1, vector<int>(n + 1, 1e9));
        dp[0][0] = 0;

        auto get_next = [](int prev, int num) {
            return prev + ((prev % 2 == num) ? 2 : 1);
        };

        for (int i = 0; i <= m; ++i) {
            for (int j = 0; j <= n; ++j) {
                if (i > 0) dp[i][j] = min(dp[i][j], get_next(dp[i - 1][j], nums1[i - 1]));
                if (j > 0) dp[i][j] = min(dp[i][j], get_next(dp[i][j - 1], nums2[j - 1]));
            }
        }
        return dp[m][n];
    }
};

class Solution {
    public int minLargest(int[] nums1, int[] nums2) {
        int m = nums1.length;
        int n = nums2.length;
        int[][] dp = new int[m + 1][n + 1];
        for (int i = 0; i <= m; ++i) Arrays.fill(dp[i], 1_000_000_000);
        dp[0][0] = 0;

        for (int i = 0; i <= m; ++i) {
            for (int j = 0; j <= n; ++j) {
                if (i > 0) dp[i][j] = Math.min(dp[i][j], getNext(dp[i - 1][j], nums1[i - 1]));
                if (j > 0) dp[i][j] = Math.min(dp[i][j], getNext(dp[i][j - 1], nums2[j - 1]));
            }
        }
        return dp[m][n];
    }

    private int getNext(int prev, int num) {
        return prev + (prev % 2 == num ? 2 : 1);
    }
}

var minLargest = function(nums1, nums2) {
    const m = nums1.length;
    const n = nums2.length;
    const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(Infinity));
    dp[0][0] = 0;

    const getNext = (prev, num) => {
        return prev + (prev % 2 === num ? 2 : 1);
    };

    for (let i = 0; i <= m; i++) {
        for (let j = 0; j <= n; j++) {
            if (i > 0) dp[i][j] = Math.min(dp[i][j], getNext(dp[i - 1][j], nums1[i - 1]));
            if (j > 0) dp[i][j] = Math.min(dp[i][j], getNext(dp[i][j - 1], nums2[j - 1]));
        }
    }
    return dp[m][n];
};
